    <td><?= $live ? '<span class="badge b-green">API — automatic</span>' : ($api ? '<span class="badge b-amber">API available — add credentials</span>' : '<span class="badge">Assisted portal filing</span>') ?></td>
    <td><select name="mode[<?= $j ?>]" style="width:auto"><?php foreach (['auto', 'approval', 'manual'] as $m): ?><option<?= $modes[$j] === $m ? ' selected' : '' ?>><?= $m ?></option><?php endforeach; ?></select></td></tr><?php endforeach; ?></tbody></table></div>
  <button class="btn btn-primary btn-sm" style="margin-top:12px">Save policy</button></form>
